/* The font itself, declared with gint's own font_t so the compiler lays the
 * bitfield byte, the pointers and the trailing metrics out exactly the way
 * gint's renderer reads them. The unnamed :24 filler is skipped by the
 * initializer, which is what C requires for unnamed bitfields. */
static font_t const wc_font = {
    "CP437",
    0,                       /* bold */
    0,                       /* italic */
    0,                       /* serif */
    0,                       /* mono */
    0,                       /* prop: fixed-width, not proportional */
    9,                      /* line_height */
    9,                      /* data_height */
    73,                      /* block_count */
    318,                      /* glyph_count */
    0,                       /* char_spacing: advance == width == 8 px */
    (void *)wc_blocks,
    (void *)wc_data,
    { .width = 8, .storage_size = 3 }
};

font_t const *wc_font_get(void) { return &wc_font; }

